// Pretty-print every workflow returned by the n8n API and aggregate into one file.
// API returns { data: [ ...workflows ] }
const payload = $input.first().json;
const workflows = payload.data || payload;
const date = new Date().toISOString().slice(0, 10);
const pretty = JSON.stringify(workflows, null, 2);
return [{
  json: {
    date,
    count: Array.isArray(workflows) ? workflows.length : 0,
    fileName: `n8n-workflows-${date}.json`
  },
  binary: {
    data: {
      data: Buffer.from(pretty, 'utf-8').toString('base64'),
      mimeType: 'application/json',
      fileName: `n8n-workflows-${date}.json`
    }
  }
}];

